let view='dashboard',selMesa=null,draft={},errs={},formMsg='',resId=null,failMsg='',tab='activas',clientTab='activas',q='',cat='Todas',pq='',modal=null,lock=false,fallo=false,okFn=null,pd={},pe={},authRole='cliente',authMode='login',authError='',quickError='',zoneFilter='Todas',capacityFilter='Todas',onlyAvailable=false,paymentMethod='',paymentBusy=false,paymentError='';
