const steps=n=>`<ol class="grid grid-cols-3 gap-2 mb-5 max-w-2xl text-sm font-semibold" aria-label="Progreso de reserva">${['Datos','Pago','Confirmación'].map((t,i)=>`<li aria-current="${i+1===n?'step':'false'}" class="rounded-xl border px-3 py-2 ${i+1===n?'border-oro/50 bg-oro/10 text-oro':i+1<n?'border-oliva/30 bg-oliva/5':'border-white/10 bg-white/5 text-white/60'}"><span class="text-[10px] opacity-80 block">PASO ${i+1}</span>${t}</li>`).join('')}</ol>`;
const cd=ts=>`<span data-exp="${ts}" class="tabular-nums font-medium"></span>`;
const cdReserva=r=>`<span data-start="${r.fecha_reserva||0}" data-exp="${r.fecha_vencimiento}" class="tabular-nums font-medium"></span>`;
const horaReserva=r=>r.fecha_reserva?D.hora(r.fecha_reserva):'—';
const duracion=ms=>{let s=Math.ceil(Math.max(0,ms)/1000);const dias=Math.floor(s/86400);s%=86400;const horas=Math.floor(s/3600);s%=3600;const minutos=Math.floor(s/60);return dias?`${dias} d ${horas} h ${minutos} min`:horas?`${horas} h ${minutos} min`:`${minutos}:${pad(s%60)}`};
const demoFecha=t=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(t)).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`};
const fechaMinima=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(Math.ceil(D.now()/60000)*60000)).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`};
const FOTOS={Entradas:'photo-1546069901-ba9599a7e63c','Platos principales':'photo-1476224203421-9ac39bcb3321',Pastas:'photo-1473093295043-cdd812d0e601',Hamburguesas:'photo-1568901346375-23c9450c58cd',Bebidas:'photo-1513558161293-cdaf765edfd7',Postres:'photo-1488477181946-6428a0291777'};
const fotoFallback=c=>`https://images.unsplash.com/${FOTOS[c]||FOTOS.Entradas}?auto=format&fit=crop&w=960&q=82`;
const fld=(n,l,v,t='text',extra='')=>`<label class="block text-sm">${l}<input name="${n}" type="${t}" value="${esc(v)}" class="inp mt-1" ${extra}><span class="err">${esc((view==='form'?errs:pe)[n]||'')}</span></label>`;
const shell=(t,b)=>`<div data-act="bg" class="modal-backdrop fixed inset-0 backdrop-blur-sm z-40 grid place-items-center p-4"><section role="dialog" aria-modal="true" aria-label="${t}" class="card p-6 w-full max-w-lg max-h-[90vh] overflow-auto fade"><div class="flex justify-between items-center mb-4"><h3 class="font-serif text-2xl">${t}</h3><button data-act="close" class="btn alt !px-3" aria-label="Cerrar diálogo">×</button></div>${b}</section></div>`;
const row=(a,b)=>`<div class="flex justify-between gap-4 py-2 border-b row-divider text-sm ticket-row"><span class="text-white/60">${a}</span><span class="text-right">${b}</span></div>`;
const tableSvg=(m,state,r)=>{
 const chairs=m.capacidad<=2?[[60,20],[60,100]]:m.capacidad<=4?[[60,18],[60,102],[18,60],[102,60]]:m.capacidad<=6?[[44,18],[76,18],[44,102],[76,102],[18,60],[102,60]]:[[40,18],[60,18],[80,18],[40,102],[60,102],[80,102],[18,60],[102,60]];
 const top=m.capacidad<=2?'<circle class="table-top" cx="60" cy="60" r="25"/>':m.capacidad<=4?'<rect class="table-top" x="35" y="35" width="50" height="50" rx="8"/>':'<rect class="table-top" x="30" y="39" width="60" height="42" rx="8"/>';
 const deadline=r?(r.estado==='pendiente_pago'?r.fecha_pago_vencimiento:r.fecha_vencimiento):0,start=r?(r.estado==='pendiente_pago'?r.fecha_creacion:r.fecha_reserva):0,ratio=deadline>start?Math.max(0,Math.min(1,(deadline-D.now())/(deadline-start))):0,circ=301.6;
 return `<svg class="table-svg" viewBox="0 0 120 120" aria-hidden="true">${chairs.map(([x,y])=>`<circle class="table-chair" cx="${x}" cy="${y}" r="5"/>`).join('')}${top}${state==='reservada'?`<circle class="table-progress" data-progress-start="${start}" data-progress-exp="${deadline}" r="48" cx="60" cy="60" stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-ratio)}"/>`:''}${state==='ocupada'?'<circle class="table-status-dot" cx="82" cy="38" r="4"/>':''}</svg>`;
};
const paymentIcons={PSE:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/>','Nequi / Daviplata':'<rect x="7" y="2" width="10" height="20" rx="2"/><path d="M10 5h4M11 18h2"/>',Tarjeta:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20M6 15h4"/>'};
const paymentIcon=m=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paymentIcons[m]}</svg>`;
const go=v=>{view=v;modal=null;lock=false;if(v==='form'){errs={};formMsg='';paymentMethod='';paymentError='';paymentBusy=false}render()};
const ask=(msg,fn)=>{okFn=fn;modal=()=>shell('Confirmar',`<p>${msg}</p><div class="flex gap-2 mt-4"><button class="btn red" data-act="yes">Confirmar</button><button class="btn alt" data-act="close">Volver</button></div>`);render()};
const run=f=>{try{f()}catch(e){D.toast(e.msg||'Ocurrió un error','err')}};
const propia=r=>{const session=D.currentSession(),contacto=V.contacto(r);return!!session&&(r.cliente_id===session.id||V.norm.correo(contacto?.correo)===V.norm.correo(session.correo))};
const floorPlan=()=>{
 const M=db().mesas,c=e=>M.filter(m=>V.estadoMesa(m)===e).length,sections=D.SECCIONES.filter(s=>zoneFilter==='Todas'||zoneFilter===s.ubicacion);
 const zoneButtons=['Todas',...D.SECCIONES.map(s=>s.ubicacion)].map(z=>`<button class="btn ${zoneFilter===z?'':'alt'}" aria-pressed="${zoneFilter===z}" data-act="zoneFilter" data-zone="${z}">${z}</button>`).join('');
 const capacityButtons=['Todas',2,4,6,8].map(n=>`<button class="btn ${capacityFilter===String(n)?'':'alt'}" aria-pressed="${capacityFilter===String(n)}" data-act="capacityFilter" data-capacity="${n}">${n==='Todas'?'Todas':`${n} personas`}</button>`).join('');
 const zones=sections.map(section=>{
  const tables=M.filter(m=>m.ubicacion===section.ubicacion&&(capacityFilter==='Todas'||m.capacidad===Number(capacityFilter))&&(!onlyAvailable||V.estadoMesa(m)==='disponible'));
  if(!tables.length)return '';
  const marker=section.id==='terraza'?'PÉRGOLA · TERRAZA ABIERTA':section.id==='ejecutivo'?'VENTANAL PANORÁMICO · GRAN VISTA':section.id==='barra'?'MOSTRADOR · BARRA':'SALÓN PRINCIPAL · VENTANA';
  return `<section class="floor-zone floor-zone-${section.id}"><div class="flex flex-wrap justify-between items-end gap-3 mb-4"><div><h3 class="font-serif text-2xl">${section.ubicacion}</h3><p class="text-sm text-white/60">${section.descripcion}</p></div><div class="flex items-center gap-3"><span class="text-xs text-white/60">${tables.length} mesas</span>${section.consumo_minimo?`<span class="badge-premium">Mínimo ${D.cop(section.consumo_minimo)} / mesa</span>`:''}</div></div><div class="venue-marker">${marker}</div><div class="floorplan-grid grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-2 sm:gap-3">${tables.map(m=>{
   const r=V.reservaDeMesa(m.id),next=V.reservasDeMesa(m.id).find(x=>x.fecha_reserva>D.now()),state=V.estadoMesa(m),color=COL[state],fill=T[FAM[state]][0],selected=selMesa===m.id;
   return `<button type="button" data-act="mesa" data-id="${m.id}" aria-pressed="${selected}" aria-label="Mesa ${pad(m.numero)}, capacidad ${m.capacidad} personas, ${state}" title="Mesa ${pad(m.numero)} · ${m.capacidad} personas · ${state}" class="floor-table-card ${state!=='disponible'?'table-live':''}" style="--table-color:${color};--table-fill:${fill}">${tableSvg(m,state,r)}<span class="table-label font-semibold">Mesa ${pad(m.numero)}</span>${badge(state)}<span class="text-xs text-white/60">${m.capacidad} personas</span>${m.consumo_minimo?`<span class="text-xs text-oro">Mínimo ${D.cop(m.consumo_minimo)}</span>`:''}${r?`<span class="text-xs font-medium" style="color:${color}">${r.estado==='pendiente_pago'?'Bloqueo de pago':cdReserva(r)}</span>`:next?`<span class="text-xs text-white/60">Próximo turno · ${D.hora(next.fecha_reserva)}</span>`:''}</button>`;
  }).join('')}</div></section>`;
 }).join('');
 return h('Plano del comedor')+`<div class="grid grid-cols-3 gap-2 sm:gap-3 mb-5">${['disponible','reservada','ocupada'].map(e=>`<div class="card p-3 sm:p-4 text-center"><div class="text-xs text-white/60 flex justify-center items-center gap-2"><i class="w-2 h-2 rounded-full" style="background:${COL[e]}"></i>${e}</div><div class="font-serif text-2xl sm:text-3xl">${c(e)}</div></div>`).join('')}</div><section class="card p-4 sm:p-5 mb-5"><div class="eyebrow mb-2">Filtros rápidos · ${M.length} mesas</div><div class="floor-filters mb-3">${zoneButtons}</div><div class="floor-filters items-center">${capacityButtons}<label class="btn alt cursor-pointer"><input type="checkbox" data-filter="available" ${onlyAvailable?'checked':''} class="mr-2">Solo disponibles</label></div></section><div class="flex flex-wrap gap-3 mb-5 text-sm" aria-label="Leyenda de estados">${['disponible','reservada','ocupada'].map(e=>`<span class="inline-flex items-center gap-2"><i class="w-2.5 h-2.5 rounded-full" style="background:${COL[e]};box-shadow:0 0 10px ${COL[e]}66"></i>${e[0].toUpperCase()+e.slice(1)}</span>`).join('')}<span class="text-white/60">· Selecciona una mesa para ver horarios</span></div><div class="floor-zones" aria-label="Zonas del comedor; desliza para cambiar">${zones||'<div class="card p-8 text-center text-white/60">No hay mesas con estos filtros. Prueba otra zona o capacidad.</div>'}</div>`;
};
const donutChart=mesas=>{
 const items=['disponible','reservada','ocupada'].map(state=>({state,count:mesas.filter(m=>V.estadoMesa(m)===state).length})),total=mesas.length,circ=263.9;
 let offset=0;
 const paths=items.map(({state,count})=>{const length=total?circ*count/total:0,path=`<circle cx="52" cy="52" r="42" fill="none" stroke="${COL[state]}" stroke-width="12" stroke-dasharray="${length} ${circ-length}" stroke-dashoffset="${-offset}"/>`;offset+=length;return path}).join('');
 return `<svg class="chart-donut" viewBox="0 0 104 104" role="img" aria-label="Ocupación: ${items.map(x=>`${x.count} ${x.state}`).join(', ')}"><circle cx="52" cy="52" r="42" fill="none" stroke="rgba(255,255,255,.09)" stroke-width="12"/>${paths}<text x="52" y="49" text-anchor="middle" fill="#f2f4f8" font-size="17" font-weight="600">${total?Math.round(items.slice(1).reduce((a,x)=>a+x.count,0)/total*100):0}%</text><text x="52" y="64" text-anchor="middle" fill="#b4bac8" font-size="7">OCUPACIÓN</text></svg>`;
};

const VIEWS={
auth(){const admin=authRole==='admin',register=!admin&&authMode==='register';return `<div class="auth-stage"><div class="auth-grid"><section class="auth-aside"><div class="auth-brand">MS / MESASERVIDA · SALA INTELIGENTE</div><div class="auth-copy"><p class="eyebrow">CONTROL OPERATIVO · BOGOTÁ</p><h2 class="auth-title">El siguiente turno empieza aquí.</h2><p>Reservas por horario, servicio de sala en tiempo real y una experiencia diseñada para la alta gastronomía.</p></div><div class="auth-copy"><span class="text-oliva">●</span> SISTEMA DE RESERVAS · COP</div></section><section class="auth-form-wrap"><p class="eyebrow mb-2">${admin?'ACCESO DE PERSONAL':'ACCESO DE CLIENTES'}</p><h2 class="font-serif text-3xl font-semibold mb-2">${register?'Crear cuenta':admin?'Bienvenido, administrador':'Bienvenido de nuevo'}</h2><p class="text-sm opacity-60 mb-6">${admin?'Ingresa con las credenciales de administración.':register?'Regístrate para reservar y gestionar tus turnos.':'Ingresa para explorar el menú y reservar tu mesa.'}</p><div class="auth-segment mb-3"><button type="button" data-act="auth-role" data-role="cliente" class="${admin?'':'active'}">Cliente</button><button type="button" data-act="auth-role" data-role="admin" class="${admin?'active':''}">Administrador</button></div>${!admin?`<div class="auth-segment mb-5"><button type="button" data-act="auth-mode" data-mode="login" class="${register?'':'active'}">Iniciar sesión</button><button type="button" data-act="auth-mode" data-mode="register" class="${register?'active':''}">Crear cuenta</button></div>`:'<div class="rounded-lg border border-oro/20 bg-oro/5 p-3 text-xs mb-5"><div class="eyebrow">ACCESO DEMO</div><div class="mt-1">admin@restaurant.com · admin123</div></div>'}${authError?`<div class="auth-error mb-4">${esc(authError)}</div>`:''}<form id="auth-form" class="space-y-4" novalidate>${register?`<label class="block text-sm">Nombre completo<input class="inp mt-1" name="nombre" autocomplete="name" required></label>`:''}<label class="block text-sm">Correo electrónico<input class="inp mt-1" name="correo" type="email" autocomplete="email" placeholder="nombre@correo.com" required></label><label class="block text-sm">Contraseña<input class="inp mt-1" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" minlength="${register?'8':'1'}" required></label>${register?'<p class="text-xs opacity-55">Usa al menos 8 caracteres.</p>':''}<button class="btn w-full mt-2" type="submit">${register?'Crear cuenta y entrar':admin?'Entrar como administrador':'Entrar como cliente'}</button></form><p class="text-[11px] opacity-40 mt-5">Autenticación de demostración en este navegador. No uses contraseñas reales.</p></section></div></div>`},
dashboard(){
 const s=db(),M=s.mesas,d=V.ocupacionPorZona(),pr=V.proximas(),agenda=V.reservasHoy(),arrivals=V.llegadasPendientes(),release=V.proximasLiberar(),act=s.reservas.filter(V.TABS.activas).length;
 const ocupado=M.filter(m=>V.estadoMesa(m)!=='disponible').length,cobrado=s.pagos.filter(p=>['aprobado','aplicado','retenido'].includes(p.estado)).reduce((a,p)=>a+p.monto,0);
 const n=D.now(),dia=24*60*60*1000,recientes=s.reservas.filter(r=>r.fecha_creacion>=n-dia).length,previas=s.reservas.filter(r=>r.fecha_creacion>=n-2*dia&&r.fecha_creacion<n-dia).length,variacion=recientes-previas;
 const st=[['Mesas',M.length],['Ocupadas ahora',ocupado],['Llegadas pendientes',arrivals.length],['Turnos de hoy',agenda.length],['Por vencer',pr.length],['Disponibles',M.filter(m=>V.estadoMesa(m)==='disponible').length],['Reservadas',M.filter(m=>V.estadoMesa(m)==='reservada').length],['Clientes',s.clientes.length],['Reservas activas',act],['Reservas nuevas · 24 h',recientes,`${variacion>0?'+':''}${variacion} vs. 24 h previas`]],icons=['plano','reservas','clientes','config','config','plano','plano','clientes','reservas','reservas'];
 return h('Panel de control')+`<div class="grid grid-cols-2 md:grid-cols-4 gap-3">${st.map(([l,v,trend],i)=>`<div class="card stat-card p-4"><div class="flex justify-between items-center gap-2"><div class="eyebrow">${l}</div><span class="text-oro">${ic(icons[i])}</span></div><div class="font-serif text-3xl">${v}</div><div class="text-xs ${trend?'text-oro':'text-white/60'} mt-1">${trend||'Actualizado en vivo'}</div></div>`).join('')}<div class="card stat-card p-4"><div class="eyebrow">Anticipos registrados</div><div class="font-serif text-2xl mt-2">${D.cop(cobrado)}</div><div class="text-xs text-white/60 mt-1">Total local · simulación</div></div></div>
 <div class="grid lg:grid-cols-2 gap-4 mt-5"><section class="card p-5"><div class="flex justify-between items-center mb-4"><div><p class="eyebrow">Por sección</p><h3 class="font-serif text-xl">Ocupación actual</h3></div><button class="btn alt" data-act="nav" data-v="plano">Abrir plano</button></div><div class="flex items-center gap-4 mb-5">${donutChart(M)}<div class="space-y-3">${['disponible','reservada','ocupada'].map(state=>`<div class="flex items-center gap-2 text-sm"><i class="w-2.5 h-2.5 rounded-full" style="background:${COL[state]}"></i><span>${state[0].toUpperCase()+state.slice(1)}</span><b class="ml-auto">${M.filter(m=>V.estadoMesa(m)===state).length}</b></div>`).join('')}</div></div><div class="space-y-4">${d.map(z=>`<div><div class="flex justify-between text-sm mb-1"><span>${z.ubicacion}</span><span>${z.ocupadas}/${z.total} · ${z.porcentaje}%</span></div><div class="h-2 rounded-full bg-white/10 overflow-hidden"><div class="h-full rounded-full bg-oliva" style="width:${z.porcentaje}%"></div></div></div>`).join('')}</div></section>
 <section class="card p-5"><div class="flex justify-between items-center mb-3"><div><p class="eyebrow">Seguimiento de sala</p><h3 class="font-serif text-xl">Próximas llegadas</h3></div>${arrivals.length?badge('confirmada',String(arrivals.length)):''}</div>${arrivals.length?arrivals.slice(0,6).map(r=>`<div class="flex justify-between items-center gap-3 py-2 border-b border-white/5"><div><b>${D.hora(r.fecha_reserva)} · Mesa ${pad(V.mesa(r.mesa_id).numero)}</b><div class="text-xs text-white/60">${esc(V.contacto(r).nombre)} · ${r.codigo_reserva}</div></div>${cdReserva(r)}</div>`).join(''):'<p class="text-sm text-white/60">No hay llegadas pendientes para hoy.</p>'}</section></div>
 <div class="grid lg:grid-cols-2 gap-4 mt-4"><section class="card p-5"><p class="eyebrow">Agenda · ${agenda.length} turnos</p><h3 class="font-serif text-xl mb-3">Reservas de hoy</h3>${agenda.length?agenda.map(r=>`<div class="flex justify-between items-center gap-3 py-2 border-b border-white/5"><div><b>${D.hora(r.fecha_reserva)}–${new Date(V.finReserva(r)).toLocaleTimeString('es-CO',{timeZone:'America/Bogota',hour:'2-digit',minute:'2-digit'})} · Mesa ${pad(V.mesa(r.mesa_id).numero)}</b><div class="text-xs text-white/60">${esc(V.contacto(r).nombre)} · ${V.mesa(r.mesa_id).ubicacion}</div></div>${badge(r.estado)}</div>`).join(''):'<p class="text-sm text-white/60">No hay turnos para hoy.</p>'}</section>
 <section class="card p-5"><p class="eyebrow">Liberaciones estimadas</p><h3 class="font-serif text-xl mb-3">Próximas mesas libres</h3>${release.length?release.slice(0,6).map(r=>`<div class="flex justify-between items-center gap-3 py-2 border-b border-white/5"><div><b>Mesa ${pad(V.mesa(r.mesa_id).numero)} · ${V.mesa(r.mesa_id).ubicacion}</b><div class="text-xs text-white/60">${r.estado==='confirmada'?'Llegada límite / turno':'Fin de turno'} · ${r.codigo_reserva}</div></div><span class="text-sm">${D.hora(r.liberacion_estimada)}</span></div>`).join(''):'<p class="text-sm text-white/60">No hay mesas con liberación programada.</p>'}</section></div>`;
},
plano(){return floorPlan()},
form(){const ms=db().mesas;return h('Garantía & reserva')+steps(1)+`<form id="rf" class="card p-6 max-w-xl space-y-3" novalidate>${formMsg?`<div class="p-3 rounded-xl bg-terra/10 text-terra text-sm">${esc(formMsg)}</div>`:''}
 ${fld('nombre','Nombre completo',draft.nombre)}${fld('documento','Documento o cédula',draft.documento,'text','inputmode="numeric"')}${fld('correo','Correo electrónico',draft.correo,'email')}${fld('telefono','Teléfono (10 dígitos)',draft.telefono,'tel')}${fld('personas','Cantidad de personas',draft.personas,'number','min="1"')}
 ${fld('fecha_reserva','Fecha y hora de la reserva',draft.fecha_reserva||'','datetime-local',`min="${fechaMinima()}" required`)}<p class="text-sm opacity-70">Turno de 2 horas. Llegada permitida hasta ${V.ventana()/60000} minutos después de la hora programada.</p>
 <label class="block text-sm">Mesa<select name="mesa_id" class="inp mt-1"><option value="">Selecciona…</option>${ms.map(m=>{const libre=draft.fecha_reserva?V.mesaLibreEn(m,draft.fecha_reserva):V.mesaLibre(m);return `<option value="${m.id}" ${draft.mesa_id===m.id?'selected':''} ${libre?'':'disabled'}>Mesa ${pad(m.numero)} · ${m.ubicacion} · ${m.capacidad} pers.${m.consumo_minimo?` · Mínimo ${D.cop(m.consumo_minimo)} en sitio`:''}${libre?'':' (cruza con otro turno o está ocupada)'}</option>`}).join('')}</select><span class="err">${esc(errs.mesa_id||'')}</span></label><button id="btnSig" class="btn w-full">Continuar al pago</button></form>`},
pago(){const r=V.res(resId);if(!r||r.estado!=='pendiente_pago')return VIEWS.fallo('El bloqueo de la mesa venció o no hay reserva en proceso.');
 const m=V.mesa(r.mesa_id),p=V.pagoDe(r.pago_id),d=r.datos;
 const descriptions={'PSE':'Débito directo desde tu cuenta bancaria','Nequi / Daviplata':'Transferencia segura desde tu celular','Tarjeta':'Débito o crédito · Visa y Mastercard'};
 return h('Garantía & anticipo')+steps(2)+`<div class="hold-banner max-w-xl p-4 mb-4 flex justify-between items-center gap-4"><div><div class="eyebrow">RETENCIÓN DE TURNO</div><div class="text-sm mt-1">Completa el anticipo antes de que venza el bloqueo de 3 minutos.</div></div><div class="hold-countdown" aria-label="Tiempo para pagar">${cd(r.fecha_pago_vencimiento||r.fecha_vencimiento)}</div></div><section class="card p-5 sm:p-6 max-w-xl"><div class="flex items-center gap-3 rounded-xl border border-oro/25 bg-oro/5 p-3 mb-4"><span class="text-oro">${ic('config')}</span><div class="text-sm"><b>Pago simulado</b><div class="text-white/60">Demostración: no se realizará ninguna transacción real.</div></div></div><div class="ticket-summary p-4"><div class="eyebrow mb-2">RESUMEN DE RESERVA</div>${row('Cliente',esc(d.nombre))}${row('Mesa',`Mesa ${pad(m.numero)} · ${m.ubicacion}`)}${row('Turno',`${D.hora(r.fecha_reserva)} a ${D.hora(V.finReserva(r))} · 2 horas`)}${row('Personas',r.cantidad_personas)}${m.consumo_minimo?row('Consumo mínimo en local',`${D.cop(m.consumo_minimo)} · se deduce de la cuenta final`):''}<div class="ticket-rule my-3"></div><div class="flex justify-between items-baseline gap-3"><span class="font-semibold">Anticipo a pagar hoy</span><span class="font-serif text-2xl sm:text-3xl">${D.cop(p.monto)}</span></div></div><fieldset class="mt-5"><legend class="eyebrow mb-2">MÉTODO DE PAGO · SIMULADO</legend><div class="space-y-2">${V.METODOS_PAGO.map(method=>`<label class="payment-option"><input type="radio" name="metodoPago" value="${method}" ${paymentMethod===method?'checked':''}><span>${paymentIcon(method)}</span><span class="min-w-0"><b class="block">${method}</b><span class="text-sm text-white/60">${descriptions[method]}</span></span></label>`).join('')}</div></fieldset><p id="payment-error" class="err mt-2" role="alert" ${paymentError?'':'hidden'}>${esc(paymentError)}</p><p id="payment-hint" class="text-xs text-white/60 mt-2">${paymentMethod?`Método seleccionado: ${paymentMethod}. Pago simulado.`:'Selecciona un método para habilitar el pago.'}</p>
 <label class="flex items-center gap-3 text-sm my-4 p-3 rounded-xl border border-white/10 bg-white/5"><input type="checkbox" id="sw" ${fallo?'checked':''}> Modo de prueba: simular pago rechazado</label><div class="flex flex-col sm:flex-row gap-2"><button id="btnPay" type="button" class="btn ol flex-1" data-act="pagar" ${!paymentMethod||paymentBusy?'disabled':''} aria-busy="${paymentBusy}">${paymentBusy?'Procesando pago…':'Pagar y confirmar reserva'}</button><button class="btn alt" data-act="abandonar">Cancelar reserva</button></div><p class="text-xs text-white/60 mt-4">El pago es simulado. Cancelación y reembolso también son demostrativos; no se mueve dinero real.</p></section>`},
fallo(msg){return h('Resultado del pago')+`<div class="card p-6 max-w-xl"><div class="rounded-xl border border-terra/30 bg-terra/10 p-4 mb-4" role="status"><b class="text-terra">Pago no aprobado</b><p class="mt-1">${esc(msg||failMsg)}</p></div><p class="text-sm text-white/60 mb-4">La reserva no fue confirmada. La mesa se libera; puedes iniciar el proceso nuevamente.</p><div class="flex flex-col sm:flex-row gap-2"><button class="btn" data-act="reintentar">Intentar otra vez</button><button class="btn alt" data-act="nav" data-v="plano">Volver al plano</button></div></div>`},
confirm(){const r=V.res(resId);if(!r)return go('plano');const m=V.mesa(r.mesa_id),c=V.contacto(r),p=V.pagoDe(r.pago_id);
 return h('Reserva confirmada')+steps(3)+`<div class="card p-5 sm:p-6 max-w-xl"><div class="rounded-xl border border-oliva/30 bg-oliva/5 p-4 mb-4 text-center" role="status"><div class="eyebrow">PAGO APROBADO · DEMOSTRACIÓN</div><div class="font-serif text-3xl text-oliva mt-1">${r.codigo_reserva}</div><p class="text-sm text-white/60 mt-1">Tu reserva quedó confirmada correctamente.</p></div><div class="hold-banner p-4 mb-4 text-center"><div class="eyebrow">TIEMPO PARA LLEGAR</div><div class="hold-countdown my-1">${r.estado==='confirmada'?cdReserva(r):badge(r.estado)}</div><div class="text-xs text-white/60">${D.hora(r.fecha_vencimiento)}</div></div><div class="ticket-summary p-4">${row('Mesa',`Mesa ${pad(m.numero)} · ${m.ubicacion}`)}${row('Cliente',esc(c.nombre))}${row('Turno',`${D.hora(r.fecha_reserva)} a ${D.hora(V.finReserva(r))} · 2 horas`)}${row('Anticipo online',`${D.cop(p.monto)} · ${p.estado}`)}${row('Método de pago',esc(p.metodo||'No especificado'))}${m.consumo_minimo?row('Consumo mínimo en local',`${D.cop(m.consumo_minimo)} · deducible de la cuenta`)+row('Total inicial reflejado',D.cop(p.monto+m.consumo_minimo)):''}${row('Liberación programada',D.hora(V.finReserva(r)))}</div><div class="flex flex-col sm:flex-row flex-wrap gap-2 mt-5 justify-center"><button class="btn" data-act="detalle" data-id="${r.id}">Ver mi reserva</button>${r.estado==='confirmada'?`<button class="btn red" data-act="cancelar" data-id="${r.id}">Cancelar reserva</button>`:''}<button class="btn alt" data-act="nav" data-v="plano">Volver al plano</button></div></div>`},
reservas(){const f=db().reservas.filter(V.TABS[tab]).filter(r=>{const c=V.contacto(r),s=q.toLowerCase();return!s||[c.nombre,c.documento,r.codigo_reserva].some(x=>String(x).toLowerCase().includes(s))}).sort((a,b)=>b.fecha_creacion-a.fecha_creacion);
 const C=[['Código',r=>r.codigo_reserva],['Cliente',r=>esc(V.contacto(r).nombre)],['Documento',r=>V.contacto(r).documento],['Correo',r=>esc(V.contacto(r).correo)],['Teléfono',r=>V.contacto(r).telefono],['Mesa',r=>pad(V.mesa(r.mesa_id).numero)],['Sección',r=>V.mesa(r.mesa_id).ubicacion],['Consumo mínimo',r=>V.mesa(r.mesa_id).consumo_minimo?D.cop(V.mesa(r.mesa_id).consumo_minimo):'—'],['Personas',r=>r.cantidad_personas],['Turno',r=>`${D.hora(r.fecha_reserva)} - ${D.hora(V.finReserva(r))}`],['Límite llegada',r=>D.hora(r.fecha_vencimiento)],['Reserva',r=>badge(r.estado)],['Pago',r=>badge(V.pagoDe(r.pago_id).estado)],['Restante',r=>r.estado==='confirmada'?cdReserva(r):'—']];
 const acts=r=>`<div class="flex flex-wrap gap-1"><button class="btn alt" data-act="detalle" data-id="${r.id}">Ver</button>${r.estado==='confirmada'?`<button class="btn ol" data-act="llegada" data-id="${r.id}">Llegada</button><button class="btn red" data-act="cancelar" data-id="${r.id}">Cancelar</button>`:''}${r.estado==='en_curso'?`<button class="btn" data-act="finalizar" data-id="${r.id}">Finalizar</button>`:''}</div>`;
 return h('Reservas')+`<div class="flex flex-wrap gap-2 mb-4">${Object.keys(V.TABS).map(t=>`<button data-act="tab" data-t="${t}" class="btn ${t===tab?'':'alt'}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}<input id="q1" class="inp !w-64" placeholder="Buscar nombre, documento o código" value="${esc(q)}"></div>`+(f.length?`<div class="card overflow-x-auto hidden lg:block"><table class="w-full text-sm"><thead><tr class="text-left opacity-60">${C.map(c=>`<th class="p-2">${c[0]}</th>`).join('')}<th></th></tr></thead><tbody>${f.map(r=>`<tr class="border-t reservation-row">${C.map(c=>`<td class="p-2">${c[1](r)}</td>`).join('')}<td class="p-2">${acts(r)}</td></tr>`).join('')}</tbody></table></div><div class="lg:hidden space-y-3">${f.map(r=>`<div class="card p-4">${C.map(c=>row(c[0],c[1](r))).join('')}<div class="mt-3">${acts(r)}</div></div>`).join('')}</div>`:'<div class="card p-8 text-center opacity-60">No hay reservas en esta vista.</div>')},
menu(){
 const a=V.esAdmin(),L=db().productos.filter(p=>(a||p.disponible)&&(cat==='Todas'||p.categoria===cat)&&p.nombre.toLowerCase().includes(pq.toLowerCase()));
 return h('Menú & catálogo')+`<div class="flex flex-wrap items-center gap-2 mb-5">${['Todas',...Object.keys(D.CATS)].map(c=>`<button data-act="cat" data-c="${c}" aria-pressed="${c===cat}" class="btn ${c===cat?'':'alt'}">${c}</button>`).join('')}<input id="q2" class="inp !w-56" aria-label="Buscar plato" placeholder="Buscar plato" value="${esc(pq)}">${a?'<button class="btn ol" data-act="nuevoProd">＋ Nuevo plato</button>':''}</div><p class="eyebrow mb-3">${L.length} referencias · imágenes por categoría</p>`+(L.length?`<div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">${L.map(p=>`<article class="card menu-item overflow-hidden ${p.disponible?'':'opacity-60'}"><div class="menu-photo"><div class="photo-fallback" aria-hidden="true">${D.CATS[p.categoria]||'MENU'}</div><img src="${esc(p.imagen_url)}" data-fallback="${esc(p.imagen_fallback||fotoFallback(p.categoria))}" alt="${esc(p.nombre)}" loading="lazy" onload="this.previousElementSibling.classList.add('loaded')" onerror="if(this.dataset.fallback){this.src=this.dataset.fallback;this.dataset.fallback=''}else{this.style.display='none'}"></div><div class="p-4"><div class="flex justify-between gap-3 items-start"><div><p class="eyebrow">${esc(p.tipo||p.categoria)}</p><b class="block mt-1">${esc(p.nombre)}</b></div><span class="text-oliva font-semibold whitespace-nowrap">${D.cop(p.precio)}</span></div><p class="text-sm text-white/60 my-3">${esc(p.descripcion)}</p>${badge(p.disponible?'aprobado':'fallido',p.disponible?'Disponible':'No disponible')}${a?`<div class="flex flex-wrap gap-1 mt-4"><button class="btn alt" data-act="editProd" data-id="${p.id}">Editar</button><button class="btn alt" data-act="togProd" data-id="${p.id}">${p.disponible?'Ocultar':'Mostrar'}</button><button class="btn red" data-act="delProd" data-id="${p.id}">Eliminar</button></div>`:''}</div></article>`).join('')}</div>`:'<div class="card p-8 text-center opacity-60">No hay platos que coincidan con estos filtros.</div>')},
misReservas(){const L=V.delSesion();return h('Mis reservas')+(L.length?`<div class="grid md:grid-cols-2 gap-4">${L.map(r=>{const m=V.mesa(r.mesa_id),p=V.pagoDe(r.pago_id);return `<div class="card p-5"><div class="flex justify-between items-center mb-2"><b class="font-serif text-xl">${r.codigo_reserva}</b>${badge(r.estado)}</div>${row('Mesa',`Mesa ${pad(m.numero)} · ${m.ubicacion}`)}${row('Turno',`${horaReserva(r)} - ${D.hora(V.finReserva(r))}`)}${row('Personas',r.cantidad_personas)}${row('Anticipo',`${D.cop(p.monto)} · ${p.estado}`)}${row('Método de pago',esc(p.metodo||'No especificado'))}${r.estado==='confirmada'?row('Tiempo',cdReserva(r))+`<button class="btn red mt-3" data-act="cancelarPropia" data-id="${r.id}">Cancelar reserva</button>`:''}</div>`}).join('')}</div>`:'<div class="card p-8 text-center opacity-60">Aún no tienes reservas. Elige una mesa en el plano.</div>')},
clientes(){const s=q.toLowerCase(),L=db().clientes.filter(c=>!s||c.nombre.toLowerCase().includes(s)||c.documento.includes(s));
 return h('Clientes')+`<input id="q3" class="inp max-w-sm mb-4" placeholder="Buscar nombre o documento" value="${esc(q)}">`+(L.length?`<div class="grid md:grid-cols-2 gap-3">${L.map(c=>{const rs=db().reservas.filter(r=>r.cliente_id===c.id),ac=rs.some(V.TABS.activas);return `<button data-act="cliente" data-id="${c.id}" class="card p-4 text-left"><b>${esc(c.nombre)}</b><div class="text-sm opacity-70">CC ${c.documento} · ${esc(c.correo)} · ${c.telefono}</div><div class="text-sm mt-1">${rs.length} reservas · ${ac?'Con reserva activa':'Sin reserva activa'}</div></button>`}).join('')}</div>`:'<div class="card p-8 text-center opacity-60">Sin resultados.</div>')},
config(){const c=db().config;
 return h('Configuración')+`<div class="card p-6 max-w-xl space-y-4"><div class="rounded-lg border border-oliva/20 bg-oliva/5 p-3"><div class="eyebrow">Anticipo obligatorio</div><strong class="font-mono text-lg">${D.cop(50000)}</strong><p class="text-sm opacity-60 mt-1">Pago simulado fijo para toda reserva.</p></div><div class="rounded-lg border border-oro/20 bg-oro/5 p-3"><div class="eyebrow">Turno estándar</div><strong class="font-mono text-lg">2 horas por mesa</strong></div><div class="rounded-lg border border-oro/20 bg-oro/5 p-3"><div class="eyebrow">Ventana de llegada</div><label class="block text-sm">Ventana de llegada (minutos desde la hora programada)<select data-cfg="minutos" class="inp mt-1">${[1,2,5,15,30].map(v=>`<option ${(c.minutos||30)===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="block text-sm">Umbral "próxima a vencer" (min)<input data-cfg="umbral" type="number" value="${c.umbral}" class="inp mt-1"></label>
 <div class="flex gap-2"><button class="btn" data-act="adelantar">Simular paso del tiempo (+5 min)</button><button class="btn red" data-act="reset">Restablecer datos</button></div></div>
 <div class="card p-6 max-w-xl mt-4 text-sm"><h3 class="font-serif text-xl mb-2">Notas de producción</h3><ul class="list-disc pl-5 space-y-1 opacity-80"><li>Transacción atómica de reserva y disponibilidad en backend.</li><li>Restricción única por correo y documento activos.</li><li>Vencimiento con hora del servidor y tarea programada.</li><li>Pagos reales (Wompi, PayU, Mercado Pago) con webhook.</li><li>Autenticación y roles reales; hoy el pago es simulado.</li></ul></div>`}
};
const detalle=id=>{const r=V.res(id),c=V.contacto(r),p=V.pagoDe(r.pago_id),m=V.mesa(r.mesa_id);return shell(r.codigo_reserva,row('Cliente',esc(c.nombre))+row('Documento',c.documento)+row('Correo',esc(c.correo))+row('Teléfono',c.telefono)+row('Mesa',`Mesa ${pad(m.numero)} · ${m.ubicacion}`)+(m.consumo_minimo?row('Consumo mínimo en sitio',D.cop(m.consumo_minimo)):'')+row('Personas',r.cantidad_personas)+row('Turno',`${D.hora(r.fecha_reserva)} - ${D.hora(V.finReserva(r))}`)+row('Límite de llegada',D.hora(r.fecha_vencimiento))+row('Creación',D.hora(r.fecha_creacion))+row('Reserva',badge(r.estado))+row('Pago',`${badge(p.estado)} ${D.cop(p.monto)}`)+row('Método de pago',esc(p.metodo||'No especificado'))+row('Referencia',p.referencia||'—'))};
const mesaModal=()=>{const m=V.mesa(selMesa),r=V.reservaDeMesa(m.id),next=V.reservasDeMesa(m.id).find(x=>x.estado==='confirmada'&&x.fecha_reserva>D.now()),state=V.estadoMesa(m),a=V.esAdmin(),puedeElegir=!m.ocupacion_manual;
 return shell(`Mesa ${pad(m.numero)}`,row('Capacidad',m.capacidad+' personas')+row('Estado',badge(state))+row('Ubicación',m.ubicacion)+(m.consumo_minimo?row('Consumo mínimo en sitio',`${D.cop(m.consumo_minimo)} · pagadero en restaurante`):'')+(r?row('Cliente',esc(V.contacto(r).nombre))+row('Código',r.codigo_reserva)+row('Turno',`${D.hora(r.fecha_reserva)} - ${D.hora(V.finReserva(r))}`)+row('Límite de llegada',D.hora(r.fecha_vencimiento))+row('Tiempo restante',cdReserva(r)):next?row('Próximo turno',`${D.hora(next.fecha_reserva)} - ${D.hora(V.finReserva(next))}`):'')
 +`<div class="mt-4 space-y-2">${puedeElegir?`<button class="btn w-full" data-act="reservar" data-id="${m.id}">Elegir horario y reservar</button>${r?'<p class="text-xs opacity-60">La mesa está ocupada en el turno actual. Elige otro horario para comprobar disponibilidad.</p>':''}`:`<button class="btn w-full" disabled>Ocupada manualmente</button>`}
 ${a&&puedeElegir&&state==='disponible'?`<button class="btn alt w-full" data-act="ocupar" data-id="${m.id}">Ocupar mesa sin reserva</button>`:''}${a&&m.ocupacion_manual?`<button class="btn alt w-full" data-act="liberar" data-id="${m.id}">Liberar mesa</button>`:''}</div>`) };
const prodModal=()=>shell(pd.id?'Editar producto':'Nuevo producto',`<form id="pf" class="space-y-3" novalidate>${fld('nombre','Nombre',pd.nombre||'')}${fld('tipo','Variedad o preparación',pd.tipo||'')}${fld('descripcion','Descripción',pd.descripcion||'')}${fld('precio','Precio (COP, entero)',pd.precio||'','number')}<label class="block text-sm">Categoría<select name="categoria" class="inp mt-1">${Object.keys(D.CATS).map(c=>`<option ${pd.categoria===c?'selected':''}>${c}</option>`).join('')}</select></label>${fld('imagen_url','Ruta de imagen',pd.imagen_url||'','text','placeholder="assets/images/dishes/bebidas/Jugo-natural.jpg"')}<label class="block text-sm">Prompt visual (inglés)<textarea name="imagen_prompt" class="inp mt-1 min-h-32">${esc(pd.imagen_prompt||'')}</textarea></label><label class="flex gap-2 text-sm"><input type="checkbox" name="disponible" ${pd.disponible!==false?'checked':''}> Disponible para clientes</label><button class="btn w-full">Guardar plato</button></form>`);
const quickRegisterModal=()=>shell('Crear cuenta de cliente',`<p class="text-sm opacity-65 mb-4">Completa tus datos para guardar el perfil y continuar con este turno.</p>${quickError?`<div class="auth-error mb-4">${esc(quickError)}</div>`:''}<form id="quick-register" class="space-y-3" novalidate>${fld('nombre','Nombre completo',draft.nombre||'')}${fld('documento','Número de documento',draft.documento||'','text','inputmode="numeric"')}${fld('correo','Correo electrónico',draft.correo||'','email')}${fld('telefono','Teléfono',draft.telefono||'','tel','inputmode="tel"')}<button class="btn w-full">Crear cuenta de cliente</button></form>`);
const addRegistrationProfileFields=()=>{
 if(authRole!=='cliente'||authMode!=='register')return;
 const form=$('#auth-form'),password=form?.querySelector('input[name="password"]')?.closest('label');if(!password)return;
 for(const[name,label,autocomplete,inputmode]of [['documento','Número de documento','off','numeric'],['telefono','Teléfono','tel','tel']]){
  const wrapper=document.createElement('label');wrapper.className='block text-sm';wrapper.textContent=label;
  const input=document.createElement('input');input.className='inp mt-1';input.name=name;input.type='text';input.autocomplete=autocomplete;input.inputMode=inputmode;input.required=true;
  wrapper.append(input);password.before(wrapper)
 }
};
const addProfilePrompt=()=>{
 if(view!=='form'||!draft.correo||!draft.documento||V.clienteRegistrado(draft.correo,draft.documento))return;
 const form=$('#rf'),notice=document.createElement('div');notice.className='card p-3 border border-oro/25 bg-oro/5';
 const text=document.createElement('p');text.className='text-sm opacity-75';text.textContent='No encontramos un perfil con ese correo y documento. Guarda tus datos para continuar con la reserva.';
 const button=document.createElement('button');button.type='button';button.className='btn alt mt-3';button.dataset.act='quick-register';button.textContent='Registrarse ahora';notice.append(text,button);form.querySelector('#btnSig').before(notice)
};
const clienteModal=id=>{const c=db().clientes.find(x=>x.id===id),rs=db().reservas.filter(r=>r.cliente_id===id);return shell(esc(c.nombre),(rs.length?rs.map(r=>{const p=V.pagoDe(r.pago_id);return `<div class="py-3 border-b row-divider text-sm">${r.codigo_reserva} · Mesa ${pad(V.mesa(r.mesa_id).numero)} · ${D.hora(r.fecha_creacion)}<div class="mt-2">${badge(r.estado)} ${badge(p.estado)} · ${D.cop(p.monto)}<div class="mt-1">Método de pago: ${esc(p.metodo||'No especificado')}</div></div></div>`}).join(''):'<p class="opacity-60">Sin historial.</p>'))};

export function render(){
 const session=D.currentSession();
 if(!session){document.body.classList.add('auth-active');$('#side').innerHTML='';$('#bar').innerHTML='';$('#userbox').classList.add('hidden');$('#app').innerHTML=`<div class="fade">${VIEWS.auth()}</div>`;if(authRole==='cliente'&&authMode==='register')addRegistrationProfileFields();$('#modal').innerHTML='';return}
 document.body.classList.remove('auth-active');
 const a=session.rol==='admin',it=NAV.filter(n=>!n[2]||(n[2]===1?a:!a)),on=v=>v===view||(['form','pago','fallo','confirm'].includes(view)&&v==='plano');
 if(a&&view==='misReservas')view='dashboard';
 if(!a&&['dashboard','reservas','clientes','config'].includes(view))view='plano';
 $('#side').innerHTML=`<div class="flex items-center gap-3 px-2 py-4 mb-4"><span class="grid place-items-center w-10 h-10 rounded-lg border border-oro/30 bg-oro/10 text-oro font-mono font-bold">MS</span><div class="brand-copy"><b class="tracking-wide">MESASERVIDA</b><p class="eyebrow mt-1">CONTROL DE SALA</p></div></div>`+it.map(([v,l])=>`<button data-act="nav" data-v="${v}" aria-current="${on(v)?'page':'false'}" title="${l}" class="flex gap-3 items-center px-3 py-2 rounded-lg text-left ${on(v)?'text-oro':'text-[var(--muted)]'}">${ic(v)}<span class="nav-label">${l}</span></button>`).join('')+`<div class="mt-auto p-2 brand-copy"><div class="eyebrow">ENTORNO DEMO</div><div class="text-xs text-white/60 mt-1">Datos guardados en este navegador</div></div>`;
 $('#bar').innerHTML=it.map(([v,l])=>`<button data-act="nav" data-v="${v}" title="${l}" class="p-2 flex flex-col items-center text-[10px] ${on(v)?'text-oro':'text-[var(--muted)]'}">${ic(v)}<span>${l.split(' ')[0]}</span></button>`).join('');
 $('#userbox').classList.remove('hidden');$('[data-session-name]').textContent=session.nombre;$('[data-session-role]').textContent=session.rol==='admin'?'ADMINISTRADOR':'CLIENTE';$('[data-session-avatar]').textContent=session.nombre.split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase();
 $('#app').innerHTML=`<div class="fade">${VIEWS[view]()}</div>`;
 if(view==='form')addProfilePrompt();
 $('#modal').innerHTML=modal?modal():'';if(modal)$('#modal [role="dialog"] button')?.focus();tickDom()}
export function tickDom(){const n=D.now();document.querySelectorAll('[data-exp]').forEach(e=>{const start=Number(e.dataset.start),waiting=Number.isFinite(start)&&start>n,target=waiting?start:Number(e.dataset.exp);e.textContent=`${waiting?'Inicia en':'Restan'} ${duracion(target-n)}`});document.querySelectorAll('.table-progress').forEach(e=>{const start=Number(e.dataset.progressStart),end=Number(e.dataset.progressExp),ratio=end>start?Math.max(0,Math.min(1,(end-n)/(end-start))):0;e.style.strokeDashoffset=String(301.6*(1-ratio))});const clock=$('[data-clock]');if(clock)clock.textContent=new Intl.DateTimeFormat('es-CO',{timeZone:'America/Bogota',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(n))+' · BOG'}
const focusBack=id=>{const e=document.getElementById(id);if(e){e.focus();e.setSelectionRange(e.value.length,e.value.length)}};
export function init(){
 D.on('change',()=>{if(view!=='form'&&!lock)render()});
 D.on('toast',({msg,tipo})=>{const t=document.createElement('div');t.className='toast card px-4 py-3 text-sm fade border-l-4';t.style.borderLeftColor={ok:COL.disponible,warn:'#e0903a',err:COL.ocupada}[tipo];t.textContent=msg;$('#toasts').append(t);setTimeout(()=>t.remove(),4500)});
 $('#nav-toggle').onclick=()=>document.body.classList.toggle('nav-collapsed');
 $('#demo-time').value=demoFecha(D.now());
 document.addEventListener('input',e=>{const t=e.target;
  if(view==='form'&&t.closest('#rf'))draft[t.name]=t.value;
  else if(t.id==='q1'||t.id==='q3'){q=t.value;render();focusBack(t.id)}else if(t.id==='q2'){pq=t.value;render();focusBack('q2')}});
 document.addEventListener('keydown',e=>{const dialog=$('#modal [role="dialog"]');if(!modal||!dialog)return;if(e.key==='Escape'){modal=null;lock=false;render();return}if(e.key!=='Tab')return;const focusable=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex]:not([tabindex="-1"])')];if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
 document.addEventListener('change',e=>{const t=e.target;
  if(t.id==='sw')fallo=t.checked;
  else if(t.name==='metodoPago'){paymentMethod=t.value;paymentError='';const button=$('#btnPay'),hint=$('#payment-hint'),error=$('#payment-error');if(button)button.disabled=paymentBusy;if(hint)hint.textContent=`Método seleccionado: ${paymentMethod}. Pago simulado.`;if(error){error.textContent='';error.hidden=true}}
  else if(t.dataset.filter==='available'){onlyAvailable=t.checked;render()}
  else if(t.dataset.cfg)run(()=>V.setConfig(t.dataset.cfg,t.value));
  else if(view==='form'&&t.name==='fecha_reserva'){draft.fecha_reserva=t.value;render()}
  else if(view==='form'&&t.name==='mesa_id')draft.mesa_id=t.value});
 document.addEventListener('submit',async e=>{e.preventDefault();
  if(e.target.id==='auth-form'){
  const f=new FormData(e.target),credentials={rol:authRole,correo:f.get('correo'),password:f.get('password')};
  try{const session=authMode==='register'&&authRole==='cliente'?await D.registerClient({...credentials,nombre:f.get('nombre'),documento:f.get('documento'),telefono:f.get('telefono')}):await D.login(credentials);authError='';view=session.rol==='admin'?'dashboard':'plano';render()}
   catch(error){authError=error.message||'No se pudo iniciar sesión.';render()}
   return
  }
  if(e.target.id==='quick-register'){
   const f=new FormData(e.target),profile={nombre:f.get('nombre'),documento:f.get('documento'),correo:f.get('correo'),telefono:f.get('telefono')};
   try{D.completeClientProfile(profile);draft={...draft,...profile};quickError='';modal=null;lock=false;formMsg='Perfil guardado. Tu turno y los datos de la reserva se conservaron.';render()}
   catch(error){quickError=error.message||'No pudimos guardar tu perfil.';modal=quickRegisterModal;render()}
   return
  }
  if(e.target.id==='tf'){const f=new FormData(e.target);run(()=>V.simularHora(f.get('fecha')))}
  if(e.target.id==='rf'){const b=$('#btnSig');b.disabled=true;b.textContent='Verificando…';await sleep(500);
   try{resId=V.iniciarReserva(draft).id;fallo=false;go('pago')}catch(x){errs=x.campos||{};formMsg=x.msg||'';if(x.msg)D.toast(x.msg,'err');render()}}
  if(e.target.id==='pf'){const f=new FormData(e.target);pd={...pd,nombre:f.get('nombre'),tipo:f.get('tipo'),descripcion:f.get('descripcion'),precio:Number(f.get('precio')),categoria:f.get('categoria'),imagen_url:f.get('imagen_url'),imagen_prompt:f.get('imagen_prompt'),disponible:!!f.get('disponible')};
   try{V.guardarProducto(pd);modal=null;lock=false;render()}catch(x){pe=x.campos||{};modal=prodModal;render()}}});
 document.addEventListener('click',async e=>{const t=e.target.closest('[data-act]');if(!t)return;const d=t.dataset,a=d.act;
  if(a==='bg'&&e.target!==t)return;
  const A={nav:()=>go(d.v),bg:()=>A.close(),close:()=>{modal=null;lock=false;render()},
  'auth-role':()=>{authRole=d.role;authMode='login';authError='';render()},'auth-mode':()=>{authMode=d.mode;authError='';render()},logout:()=>{D.logout();view='dashboard';authRole='cliente';authMode='login';authError='';render()},
  mesa:()=>{selMesa=d.id;modal=mesaModal;render()},
  reservar:()=>{const session=D.currentSession()||{};draft={nombre:session.nombre||'',documento:session.documento||'',correo:session.correo||'',telefono:session.telefono||'',personas:'',mesa_id:d.id};quickError='';go('form')},
  'quick-register':()=>{quickError='';lock=true;modal=quickRegisterModal;render()},
  ocupar:()=>run(()=>{V.ocupar(d.id);modal=null;render()}),liberar:()=>run(()=>{V.liberar(d.id);modal=null;render()}),
  zoneFilter:()=>{zoneFilter=d.zone;render()},capacityFilter:()=>{capacityFilter=d.capacity;render()},
  pagar:async()=>{if(paymentBusy)return;if(!paymentMethod){paymentError='Selecciona un método de pago para continuar';const error=$('#payment-error');if(error){error.textContent=paymentError;error.hidden=false}return}paymentBusy=true;t.disabled=true;t.setAttribute('aria-busy','true');t.textContent='Procesando pago…';await sleep(900);try{if(V.pagar(resId,fallo,paymentMethod)){paymentBusy=false;go('confirm')}else{paymentBusy=false;failMsg='El pago fue rechazado y la reserva no se confirmó.';go('fallo')}}catch(x){paymentBusy=false;failMsg=x.msg||'No se pudo procesar el pago.';go('fallo')}},
  abandonar:()=>{V.abandonar(resId);go('plano')},reintentar:()=>go('form'),
  detalle:()=>{modal=()=>detalle(d.id);render()},
  cancelar:()=>ask('¿Cancelar esta reserva? El anticipo se reembolsa solo si han pasado menos de 10 minutos desde su creación.',()=>{try{V.cancelar(d.id);if(view==='confirm')go('misReservas')}catch(error){D.toast(error.msg||'No se pudo cancelar la reserva','err')}}),
  cancelarPropia:()=>ask('¿Cancelar tu reserva? El anticipo se reembolsa solo si han pasado menos de 10 minutos desde su confirmación.',()=>run(()=>V.cancelarPropia(d.id))),
  llegada:()=>run(()=>V.llegada(d.id)),finalizar:()=>run(()=>V.finalizar(d.id)),
  yes:()=>{const f=okFn;modal=null;render();f&&f()},
  tab:()=>{tab=d.t;render()},cat:()=>{cat=d.c;render()},
  nuevoProd:()=>{pd={};pe={};lock=true;modal=prodModal;render()},editProd:()=>{pd={...db().productos.find(p=>p.id===d.id)};pe={};lock=true;modal=prodModal;render()},
  togProd:()=>V.toggleProducto(d.id),delProd:()=>ask('¿Eliminar este producto?',()=>V.eliminarProducto(d.id)),
  cliente:()=>{modal=()=>clienteModal(d.id);render()},
  adelantar:()=>V.adelantar(Number(d.min||5)),'hora-real':()=>{V.restaurarHora();$('#demo-time').value=demoFecha(D.now())},reset:()=>ask('Se borrarán todos los cambios y se restaurarán los datos de demostración.',()=>{D.reset();go('dashboard')})};
  await A[a]?.()});
 render()}
